def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    MASK = 8
    mask = g == MASK
    ys, xs = np.where(mask)
    y0, x0, y1, x1 = ys.min(), xs.min(), ys.max(), xs.max()
    known = ~mask
    val = g.copy()

    def crop_box():
        return val[y0:y1 + 1, x0:x1 + 1].copy()

    emit(crop_box(), "Allocate the output: the patch hidden under the 8-block (still 8 where unknown).")

    # --- find the mirror axes (x -> ax - x, y -> ay - y) from the unmasked cells ---
    def best_axis(axis_len, other_len, getter):
        best = None
        for a in range(1, 2 * axis_len - 1):
            agree = disagree = 0
            for i in range(axis_len):
                j = a - i
                if j <= i or j >= axis_len:
                    continue
                for o in range(other_len):
                    v1, k1 = getter(i, o)
                    v2, k2 = getter(j, o)
                    if k1 and k2:
                        if v1 == v2:
                            agree += 1
                        else:
                            disagree += 1
            score = (disagree == 0, agree - 50 * disagree)
            if best is None or score > best[0]:
                best = (score, a)
        return best[1]

    ax = best_axis(W, H, lambda x, y: (g[y, x], known[y, x]))
    ay = best_axis(H, W, lambda y, x: (g[y, x], known[y, x]))

    def inside(p):
        return 0 <= p[0] < H and 0 <= p[1] < W

    # --- pass 1: global mirror partners ---
    changed = True
    while changed:
        changed = False
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if known[y, x]:
                    continue
                for p in [(y, ax - x), (ay - y, x), (ay - y, ax - x)]:
                    if inside(p) and known[p]:
                        val[y, x] = val[p]
                        known[y, x] = True
                        changed = True
                        break
    emit(crop_box(), "Fill masked cells from their left-right / up-down mirror partners (axes at %.1f, %.1f)." % (ax / 2, ay / 2))

    # --- pass 2: locally validated diagonal symmetries ---
    maps = []
    for k in range(-(W - 1), H):
        maps.append(lambda y, x, k=k: (x + k, y - k))          # transpose with shift
    for c in range(0, H + W - 1):
        maps.append(lambda y, x, c=c: (c - x, c - y))          # anti-transpose about centre c
    R = 6

    def window_stats(y, x, f):
        agree = disagree = 0
        for yy in range(max(0, y - R), min(H, y + R + 1)):
            for xx in range(max(0, x - R), min(W, x + R + 1)):
                if not known[yy, xx]:
                    continue
                p = f(yy, xx)
                if inside(p) and known[p]:
                    if val[yy, xx] == val[p]:
                        agree += 1
                    else:
                        disagree += 1
                        if disagree > 0:
                            return agree, disagree
        return agree, disagree

    changed = True
    while changed:
        changed = False
        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if known[y, x]:
                    continue
                best = None
                for f in maps:
                    p = f(y, x)
                    if not (inside(p) and known[p]):
                        continue
                    agree, disagree = window_stats(y, x, f)
                    if disagree == 0 and agree >= 10:
                        if best is None or agree > best[0]:
                            best = (agree, p)
                if best is not None:
                    val[y, x] = val[best[1]]
                    known[y, x] = True
                    changed = True
    emit(crop_box(), "Fill the cells whose mirrors fall outside the grid using the locally verified transpose / anti-transpose partner.")

    # --- fallback for anything still unknown ---
