        for y in range(y0, y1 + 1):
            for x in range(x0, x1 + 1):
                if not known[y, x]:
                    val[y, x] = bg
                    known[y, x] = True

    out = crop_box()
    emit(out, "Final: the restored patch under the 8-block.")
    return out
